PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?nombre WHERE {
  {
    SELECT ?c (COUNT(DISTINCT ?v) AS ?n) WHERE {
      ?v a energia:DetectedVenting ; energia:inConcession ?c ; energia:date ?d .
      FILTER(STR(?d) >= "2024-01-01")
    } GROUP BY ?c
  }
  ?c energia:name ?nombre .
}
ORDER BY DESC(?n)
LIMIT 5
